// chrome-extension-release's reusable workflows + composite actions moved out of
// Claudinite core (.github/) and into the pack, vendored into each consumer's own
// .github/ (#276). GitHub only resolves a reusable workflow / composite action
// from a repo's own .github/, never from a packs/… subdir, so "into the pack"
// means the pack holds the templates and each consumer hosts a managed copy.
//
// This record is the transition's whole machinery:
//   - appliesTo    — the gate: only a repo whose orchestrator is named
//                    "Release to Chrome Store" (the consumers). Claudinite carries
//                    a file of the same path named "… (reusable)", so it's skipped.
//   - materialize  — vendor the four reusable workflows + three composite actions
//                    verbatim into the consumer's .github/ (idempotent; overwrites
//                    on drift, so a hand-edited copy self-heals).
//   - rewrite      — repoint the orchestrator's three cross-repo @main calls at the
//                    local vendored files, preserving any per-repo build_env tweak.
//   - legacyPresent — telemetry: still on the old shape while anything under
//                    .github/workflows/ references Claudinite's core release
//                    workflows @main.
//
// The check-layer tolerance is driven by migrationActive('chrome-release-vendoring')
// (registry.mjs), which ends on its own once this record ages out of the recency
// window. The canon's now-unused core release plumbing (the four workflows + two
// composite actions this record vendored into the consumers — NOT report-failure,
// which is shared canon infrastructure that non-chrome workflows call @main
// directly) stays in the canon until someone sweeps it by hand, together with the
// inline references that name it — the barriers `except` entries in the canon's
// .claudinite-checks.json, the .github/workflows/README.md links, and this
// migration's own tests. (A past automated retirement deleted them on fleet
// telemetry alone and broke the canon's CI with 53 stale-ref findings.)
const STUB = '.github/workflows/chrome-extension-release.yml';
const S = 'packs/chrome-extension-release/stubs';

export default {
  id: 'chrome-release-vendoring',
  landed: '2026-07-13',
  version: 1,
  summary: 'chrome-extension-release reusable workflows + composite actions vendored from Claudinite core into each consumer repo (#276)',

  // Only touch a repo that ships the pipeline — its orchestrator is named
  // "Release to Chrome Store" (or the legacy "Release"). `read(path)` returns the
  // file's content or null.
  appliesTo: async (read) => {
    const text = await read(STUB);
    if (!text) return false;
    const name = /^name:\s*['"]?(.+?)['"]?\s*$/m.exec(text)?.[1];
    return name === 'Release to Chrome Store' || name === 'Release';
  },

  // Vendor the reusable workflows + actions verbatim (the create-package reusable
  // is renamed from chrome-extension-release.yml to avoid colliding with the
  // orchestrator's own filename inside one repo).
  materialize: [
    { template: `${S}/workflows/chrome-extension-create-package.yml`, dest: '.github/workflows/chrome-extension-create-package.yml' },
    { template: `${S}/workflows/chrome-extension-publish-store.yml`, dest: '.github/workflows/chrome-extension-publish-store.yml' },
    { template: `${S}/workflows/chrome-extension-daily-release.yml`, dest: '.github/workflows/chrome-extension-daily-release.yml' },
    { template: `${S}/workflows/deploy-privacy-page.yml`, dest: '.github/workflows/deploy-privacy-page.yml' },
    { template: `${S}/actions/read-release-config/action.yml`, dest: '.github/actions/read-release-config/action.yml' },
    { template: `${S}/actions/read-release-config/read-config.mjs`, dest: '.github/actions/read-release-config/read-config.mjs' },
    { template: `${S}/actions/bump-extension-patch/action.yml`, dest: '.github/actions/bump-extension-patch/action.yml' },
    { template: `${S}/actions/bump-extension-patch/bump.mjs`, dest: '.github/actions/bump-extension-patch/bump.mjs' },
    { template: `${S}/actions/report-failure/action.yml`, dest: '.github/actions/report-failure/action.yml' },
  ],

  // Repoint the orchestrator's three @main calls at the local vendored files.
  rewrite: [
    { file: STUB, replace: [
      { from: 'missingbulb/Claudinite/.github/workflows/chrome-extension-release.yml@main', to: './.github/workflows/chrome-extension-create-package.yml' },
      { from: 'missingbulb/Claudinite/.github/workflows/chrome-extension-publish-store.yml@main', to: './.github/workflows/chrome-extension-publish-store.yml' },
      { from: 'missingbulb/Claudinite/.github/workflows/chrome-extension-daily-release.yml@main', to: './.github/workflows/chrome-extension-daily-release.yml' },
    ] },
  ],

  // A repo is still on the legacy shape while anything under .github/workflows/
  // still references Claudinite's core release workflows @main.
  legacyPresent: async (exists, read) => {
    const text = (await read(STUB)) || '';
    return text.includes('missingbulb/Claudinite/.github/workflows/chrome-extension-');
  },
};

import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { MIGRATION_FILE, migrationDirs, migrationActive, recordName, flowOf } from '../checks/helpers/active-migrations.mjs';

// <corpus>/engine/migrations/ — records are addressed corpus-relative, because they
// no longer share one directory with this module: an engine record sits beside it,
// a pack's under that pack.
const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));

// Each migration lives in its own folder under the flow that owns it — an engine
// record beside this registry, a pack's under that pack — so a record can carry
// assets of its own and each flow can ship exactly its own set. The discovery
// surface — the roots, the folder listing, the recency predicate, and
// `migrationActive` — lives in the vendored engine lib
// (engine/checks/helpers/active-migrations.mjs) because pack CHECKS consult it and packs import
// only the engine surface (pack-independence); this registry re-exports it so
// canon-side callers keep one import home.
export { MIGRATION_FILE, migrationActive, recordName };

// Structural discovery, like packs/ and skills/: every
// <flow>/migrations/<landed-date>-<slug>/migration.mjs is a spec. ALL records
// present load — the apply/backfill path is unconditional, and FETCHING decides
// relevance: a vendored consumer mount carries only the recent records
// (vendoring's recency window), while a dormant project baselining out of a
// fresh canon clone sees every record ever landed and applies what it needs.
// Each object carries its `dir` — the record's CORPUS-RELATIVE path, which both
// names the record and says which flow owns it.
export async function loadMigrations() {
  const out = [];
  for (const d of migrationDirs()) {
    const spec = (await import(pathToFileURL(join(corpusRoot, d, MIGRATION_FILE)).href)).default;
    const record = { dir: d, ...spec };
    // Validated at LOAD, so a retired field cannot reach a flow that would ignore it,
    // and a malformed apply-stage declaration cannot reach the flow that acts on it.
    assertNoAgenticNote(record);
    assertApplyStageDeclaration(record);
    out.push(record);
  }
  return out;
}

// Read side — "prefer Y, fall back to X": the ordered list of acceptable paths
// for a canonical target (canonical first, then its legacy aliases). A tolerance
// point consults this instead of hardcoding its own LEGACY_* constant, so a
// rename is declared once here and every reader picks it up. Unknown targets
// resolve to just themselves.
export function resolvePath(migrations, canonical) {
  for (const m of migrations) {
    for (const a of m.aliases ?? []) {
      if (a.canonical === canonical) return [a.canonical, ...(a.legacy ?? [])];
    }
  }
  return [canonical];
}

// Write side — "and rename X -> Y": for each alias whose legacy path still
// exists and whose canonical does not, move legacy -> canonical. `exists` and
// `move` are injected so the same logic drives a local checkout (sync fs) or a
// future API applier (async). Idempotent — a no-op once the rename is done.
export async function applyFileAliases(migration, { exists, move }) {
  const moved = [];
  for (const a of migration.aliases ?? []) {
    for (const legacy of a.legacy ?? []) {
      if ((await exists(legacy)) && !(await exists(a.canonical))) {
        await move(legacy, a.canonical);
        moved.push(`${legacy} -> ${a.canonical}`);
      }
    }
  }
  return moved;
}

// Write side — "vendor these pack templates into the repo": for each declared
// materialization {template, dest}, copy the canon template to its destination
// when the dest is missing or has drifted from the template (idempotent; a
// hand-edited copy self-heals on the next pass). `readTemplate` reads from the
// canon (the pack tree / mounted .claudinite), `read`/`write` act on the consumer
// repo — the source and destination roots differ in a consumer, so they are
// distinct injected readers. Gated by the migration's `appliesTo` so it only
// touches repos that ship the pipeline (never the canon repo itself).
// A materialization whose dest is a WORKFLOW FILE can only be written by a caller that
// can get it delivered. The nightly converge pushes with the Action's GITHUB_TOKEN, which
// GitHub never lets write under `.github/workflows/`, and the refusal rejects the whole
// ref — so writing one into a tree that is about to be pushed by such a caller does not
// deliver a workflow, it fails the entire converge and everything else riding it.
//
// The capable caller announces itself with this variable. The pack update flow sets it
// when it can WITHHOLD those paths from its commit and hand them to the apply stage;
// anything else — an older vendored worker, a hand-run `node engine/migrations/apply.mjs`, CI —
// leaves it unset and the workflow materialization is skipped with a note.
//
// An ENV HANDSHAKE rather than a probe of the repo on disk, because what matters is what
// the RUNNING process can do and the disk cannot answer that: the vendor step earlier in
// the same cycle replaces the on-disk worker with the new one while the old code is still
// executing.
export const WITHHOLD_CAPABLE_ENV = 'CLAUDINITE_CAN_WITHHOLD_WORKFLOWS';
const WORKFLOW_DEST = '.github/workflows/';
export const callerCanDeliverWorkflows = (env = process.env) => env[WITHHOLD_CAPABLE_ENV] === '1';

export async function applyMaterializations(migration, { readTemplate, read, write, env = process.env }) {
  if (!migration.materialize?.length) return [];
  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
  const done = [];
  for (const { template, dest } of migration.materialize) {
    const content = await readTemplate(template);
    if (content == null) continue; // template missing (partial mount) — skip, never clobber with nothing
    if ((await read(dest)) === content) continue; // already vendored, unchanged
    if (dest.startsWith(WORKFLOW_DEST) && !callerCanDeliverWorkflows(env)) {
      // Reported rather than silent — a silent skip reads as "already current". A caller
      // that can withhold writes it on a later cycle.
      done.push(`SKIPPED ${dest} (workflow file; this caller cannot deliver one)`);
      continue;
    }
    await write(dest, content);
    done.push(`${dest} <- ${template}`);
  }
  return done;
}

// Write side — "rewrite these refs in place": for each declared file, apply its
// replacements (only those still matching), writing back when anything changed.
// Idempotent — a no-op once nothing matches. Preserves the rest of the file, so
// per-repo tweaks the template can't carry (e.g. an uncommented build_env block)
// survive. Same `appliesTo` gate.
//
// A replacement is either LITERAL (`{ from, to }`) or a PATTERN
// (`{ pattern: /…/g, to }`) — the regex-first shape engine migrations are meant to
// take (DESIGN §2.3), for the changes where no literal is common across repos.
// The pattern must be global, because every replacement here means replace-ALL:
// a non-global regex would silently rewrite only the first occurrence and leave a
// half-migrated file that reads as migrated.
export async function applyRewrites(migration, { read, write }) {
  if (!migration.rewrite?.length) return [];
  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
  const done = [];
  for (const { file, replace } of migration.rewrite) {
    const text = await read(file);
    if (text == null) continue;
    let next = text;
    for (const r of replace ?? []) {
      if (r.pattern !== undefined) {
        if (!(r.pattern instanceof RegExp) || !r.pattern.global) {
          throw new Error(`migration ${migration.id}: rewrite pattern for ${file} must be a global RegExp — a non-global one rewrites only the first match`);
        }
        next = next.replace(r.pattern, r.to);
      } else {
        next = next.split(r.from).join(r.to);
      }
    }
    if (next !== text) { await write(file, next); done.push(file); }
  }
  return done;
}

// The declaration a pack-seeding op writes into. Fixed, not a parameter: this op
// declares PACKS, and a repo's declaration lives in exactly one file. A `file` knob
// would quietly make it a general JSON editor, which is a much larger thing to own.
export const DECLARATION = '.claudinite-checks.json';

// Write side — "every member should now declare this pack": for each declared
// `{ id, config }`, add that pack to the member's `packs` when it is absent, and
// fill in a `config` the entry does not already carry. The op the other three could
// not express — `materialize` writes a whole template (it would clobber a per-repo
// declaration) and `rewrite` replaces literal text (declarations share no literal
// across repos) — and the shape a fleet-wide capability change actually has: a pack
// every member should run, whose parameters the canon knows and the member cannot
// derive.
//
// SEEDING, NEVER OVERRIDING. A pack the repo already declares keeps its entry, and a
// config it already carries is left exactly as it is: both are that repo's decisions,
// and a migration that reasserted them would fight the project every night. That
// makes the op idempotent by construction — a no-op once the entry is there.
//
// ORDER MATTERS AROUND IT. Declaring a pack whose code is not in the member's mount
// is a blocking `config` error there, so the caller must re-converge the mount after
// applying (baselining does; see its worker). This module only writes the file.
//
// It round-trips the file through JSON rather than editing settings as text, so the
// result is canonical 2-space settings with a trailing newline (what `--init` writes,
// and what every fleet declaration already is). Malformed JSON is left alone: the
// world runner reports it as the settings error it is, and a migration is not the
// place to guess at a repair. Same `appliesTo` gate as the other write ops.
export async function applyPackDeclarations(migration, { read, write }) {
  if (!migration.declarePacks?.length) return [];
  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
  const raw = await read(DECLARATION);
  if (raw == null) return [];                       // not a member — nothing to declare into
  let config;
  try { config = JSON.parse(raw); } catch { return []; }
  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
  const packs = Array.isArray(config.packs) ? [...config.packs] : [];
  const idOf = (e) => (typeof e === 'string' ? e : e?.id);
  const done = [];
  for (const { id, config: packConfig } of migration.declarePacks) {
    const at = packs.findIndex((e) => idOf(e) === id);
    if (at === -1) {
      packs.push(packConfig ? { id, config: packConfig } : id);
      done.push(`${DECLARATION}: declared ${id}`);
      continue;
    }

// The write-surface gate for the growth PROMOTE stage (tasks/growth-promote/, this pack).
//
// Promote's write surface is bounded to the shared canon's two homes — packs/
// and skills/. This module is the GUARANTEE: any changed path outside packs/ or
// skills/ fails the gate. The promote AGENT never runs it and needn't know it
// exists — CI runs it automatically on the promote PR (checks-ci.yml, gated on
// the growth-promote branch prefix). The corpus principle it enforces: prose is
// a request; the post-hoc diff check is the guarantee.
//
// Why CI branch-gates it instead of registering it as a pack/skill check that
// runs on every PR: the "packs/skills only" boundary is true for PROMOTE alone —
// an ordinary engine change legitimately edits checks/, engine/, … Nothing in
// the tree marks a diff as a promote run, so no always-on check could self-gate
// to promote; the promote PR's branch prefix is the signal CI keys on.
import { buildContext } from '../../../../engine/checks/helpers/repo-context.mjs';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';

const inBounds = (p) => p.startsWith('packs/') || p.startsWith('skills/');

const rule = {
  id: 'promote-scope',
  severity: 'blocking',
  description: 'The growth promote stage writes only under packs/ or skills/',
  doc: '.claudinite/local/packs/canon-curation/tasks/growth-promote/task.md',
  why: 'promote runs unattended with a fleet-wide token; a write outside the canon homes escapes the review-by-blast-radius boundary the growth lifecycle is built on',

  // Every path the branch touches vs the merge-base — added/modified/untracked
  // (allFiles in changed mode) plus deletions — that is not under packs/ or
  // skills/ is one finding. No merge-base ⇒ no diff to scope ⇒ nothing to certify;
  // the CLI wrapper treats that as a hard refusal rather than a silent pass.
  run(ctx) {
    if (!ctx.mergeBase) return [];
    const touched = [...new Set([...ctx.allFiles, ...ctx.deleted])];
    return touched
      .filter((p) => !inBounds(p))
      .sort()
      .map((p) =>
        finding(rule, {
          file: p,
          what: `the promote phase touched ${p}, outside packs/ and skills/`,
          fix: 'a promoted lesson is portable canon — home it in a pack (prose or checks) or a skill; a lesson that can only live outside packs/ and skills/ is out of promote scope, so leave it local',
        })
      );
  },
};

export default rule;

// CLI — CI runs this on the promote PR: `node .claudinite/local/packs/canon-curation/promote-scope.mjs [root]`.
//   exit 0 — every changed path is under packs/ or skills/ (certified)
//   exit 1 — one or more stray paths (the boundary was breached; fail the PR)
//   exit 2 — no merge-base with the base branch, so the diff can't be scoped
if (process.argv[1] && (await import('node:fs')).realpathSync(process.argv[1]) === (await import('node:url')).fileURLToPath(import.meta.url)) {
  const root = process.argv[2] || process.cwd();
  const ctx = buildContext({ root, mode: 'changed' });
  if (!ctx.mergeBase) {
    console.error('promote-scope: no merge-base with the base branch — cannot scope the diff; refusing to certify.');
    process.exit(2);
  }
  const findings = rule.run(ctx);
  if (findings.length) {
    console.error(`promote-scope: FAIL — the promote phase may write only under packs/ or skills/, but this branch also touches ${findings.length} path(s):`);
    for (const f of findings) console.error(`  - ${f.file}`);
    console.error('\nHome each promoted lesson in a pack (prose or checks) or a skill; leave anything that can only live elsewhere local. Do not reach past packs/ and skills/.');
    process.exit(1);
  }
  console.log('promote-scope: OK — every changed path is under packs/ or skills/.');
}

import { finding } from '../../engine/checks/helpers/findings.mjs';
import { migrationActive } from '../../engine/checks/helpers/active-migrations.mjs';

// The chrome-extension-release pipeline is VENDORED into each consumer's own
// .github/: the orchestrator (this STUB_FILE, named "Release to Chrome Store")
// owns the triggers and calls three LOCAL reusable workflows, which — with the
// privacy-page reusable and three composite actions — the pack materializes
// alongside it. Nothing references Claudinite's core .github/ any more; the whole
// set runs inside the repo. The pack keeps the copies in sync (baselining
// re-materializes on drift), so a consumer hosts the pipeline without owning it.
//
// The rename that made vendoring possible: the create-package reusable was
// `chrome-extension-release.yml` in the canon, which would collide with the
// orchestrator's own filename inside one repo, so it's vendored as
// `chrome-extension-create-package.yml`. STUB_FILE (the orchestrator) keeps its
// name — that's the fingerprint DESIGN.md pins the conformance suite to, and the
// failure-reporter issue keys ("Release: Create Package", …) live in the vendored
// reusables. The daily schedule is contract too: STUB_CRON pins every repo's
// nightly release to the same slot. The privacy page has no orchestrator entry of
// its own: it redeploys as part of every publish (the publish reusable's
// deploy-privacy-page leg).
//
// Migration tolerance: while `chrome-release-vendoring` is recent, a repo still
// on the pre-vendoring shape (the orchestrator calling Claudinite's core
// workflows @main) is TOLERATED — baselining vendors it, no red window. Once the
// record ages out of the recency window, migrationActive() flips false and the
// tolerance is gone: every up-to-date repo has vendored by then, and a repo
// still on @main is flagged.
export const STUB_FILE = 'chrome-extension-release.yml';
export const STUB_NAME = 'Release to Chrome Store';
export const LEGACY_STUB_NAMES = ['Release'];
export const STUB_CRON = '30 0 * * *';

// The create-package reusable's canon filename (pre-vendoring), still the name a
// legacy orchestrator calls @main — kept for the fingerprint + tolerance.
export const LEGACY_CREATE_PACKAGE = 'chrome-extension-release.yml';
// Its vendored filename (renamed to avoid colliding with the orchestrator).
export const VENDORED_CREATE_PACKAGE = 'chrome-extension-create-package.yml';

// The three reusable workflows the orchestrator calls locally.
export const ORCHESTRATOR_CALLS = [
  VENDORED_CREATE_PACKAGE,
  'chrome-extension-publish-store.yml',
  'chrome-extension-daily-release.yml',
];
// Every reusable workflow that must be vendored under .github/workflows/ (the
// three the orchestrator calls, plus the privacy-page reusable the publish one
// calls).
export const VENDORED_WORKFLOWS = [...ORCHESTRATOR_CALLS, 'deploy-privacy-page.yml'];
// Every composite action that must be vendored under .github/actions/<name>/.
export const VENDORED_ACTIONS = ['read-release-config', 'bump-extension-patch', 'report-failure'];

export const VENDORING_MIGRATION = 'chrome-release-vendoring';

// A repo is on the pre-vendoring shape when its orchestrator still calls one of
// Claudinite's core release workflows @main.
const LEGACY_CANON_REF = /missingbulb\/Claudinite\/\.github\/workflows\/chrome-extension-[a-z-]+\.yml@/;

