121	// the "task statuses out of the conversation logs" half of the census (owner,
122	// 2026-08-06). Same single-home rule: renderer and parser sit here together.
123	
124	export const TASK_EXEC_STATUSES = Object.freeze([
125	  // The dispatch ran to completion within its ceiling; the issue was closed.
126	  'success',
127	  // The run failed (task failure or ceiling violation); converged to needs-human.
128	  'failed',
129	  // The dispatch named a task the repo no longer carries (file gone, pack
130	  // undeclared) — the executor closed the issue as obsolete. Not a failure.
131	  'task-gone',
132	  // The dispatch was malformed (bad path shape, unparseable declaration) and was
133	  // converged to needs-human without running.
134	  'invalid',
135	]);
136	
137	export const TASK_EXEC_TAG = 'claudinite-task-exec';
138	
139	export const renderTaskExec = ({ pack, task, slotId, status }) =>
140	  `${TASK_EXEC_TAG} ${VERSION} ${pack}/${task} [${slotId ?? 'unknown'}] ${status}`;
141	
142	const EXEC_LINE_RE = new RegExp(
143	  String.raw`(?:^|\s)${TASK_EXEC_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
144	);
145	
146	export function parseTaskExec(line) {
147	  const m = EXEC_LINE_RE.exec(line);
148	  if (!m) return null;
149	  const [, pack, task, slotId, status] = m;
150	  if (!TASK_EXEC_STATUSES.includes(status)) return null;
151	  return { pack, task, slotId, status };
152	}
153	
154	export function parseTaskExecs(text) {
155	  const out = [];
156	  for (const line of String(text ?? '').split('\n')) {
157	    const rec = parseTaskExec(line);
158	    if (rec) out.push(rec);
159	  }
160	  return out;
161	}
